The following code is a simple context manager that acquires three resources in order and releases them in reverse order. If acquiring a resource fails, any resources already acquired are released before the exception is allowed to propagate.
import contextlib
class ThreeResources:
    def __init__(self):
        self.r1 = None
        self.r2 = None
        self.r3 = None

    def __enter__(self):
        try:
            self.r1 = acquire_r1()
            try:
                self.r2 = acquire_r2()
                try:
                    self.r3 = acquire_r3()
                except:
                    release_r2(self.r2)
                    raise
            except:
                release_r1(self.r1)
                raise
        except:
            raise
        return self.r1, self.r2, self.r3

    def __exit__(self, exc_type, exc_value, traceback):
        release_r3(self.r3)
        release_r2(self.r2)
        release_r1(self.r1)

